INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch08$PT159-S1-Q8$batch08$, 159, 1, 8, $batch08$Strengthen$batch08$, $batch08$Scientists found the remains of several species of mites trapped in rocks in a high-altitude cave. Radioactive dating shows that the mites were trapped about 2,000 years ago. The mite species in the rocks no longer live in the vicinity of the cave, but they are found a few miles away in a cooler area. Therefore, the area around the cave was probably cooler 2,000 years ago, since _______.$batch08$, $batch08$The conclusion of the argument is most strongly supported if which one of the following completes the passage?$batch08$, $batch08$A$batch08$, true, $batch08$Batch 08; question text from local bank.$batch08$ FROM lr_sections s WHERE s.preptest=159 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch08$PT159-S1-Q8$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$A$batch08$, $batch08$the mite species found in the rocks can only survive in very specific climates$batch08$, $batch08$Correct$batch08$, true FROM lr_questions q WHERE q.qid=$batch08$PT159-S1-Q8$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$A$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$B$batch08$, $batch08$the cooler area a few miles away from the cave also has a somewhat wetter climate$batch08$, $batch08$Weaken$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT159-S1-Q8$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$B$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$C$batch08$, $batch08$the mite species that were trapped in the rocks did not live in the vicinity of the cave much earlier than 2,000 years ago$batch08$, $batch08$Out of Scope$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT159-S1-Q8$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$C$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$D$batch08$, $batch08$the mite species found in the rocks only live at high altitudes$batch08$, $batch08$Weaken$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT159-S1-Q8$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$D$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$E$batch08$, $batch08$there are fewer mite species living in the vicinity of the cave today than there were 2,000 years ago$batch08$, $batch08$Out of Scope$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT159-S1-Q8$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$E$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch08$PT159-S1-Q8$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch08$Conclusion$batch08$, $batch08$The area around the cave was probably cooler 2,000 years ago.$batch08$), (1, $batch08$Evidence$batch08$, $batch08$Mites trapped in the cave rock 2,000 years ago no longer live near the cave, but they do live a few miles away in a cooler area.$batch08$), (2, $batch08$Evaluate$batch08$, $batch08$The argument treats the mites as a thermometer: they lived here then, they live somewhere cooler now, so it used to be cooler here. That only works if the mites are picky about climate. If they could live almost anywhere, their move tells us nothing about temperature.$batch08$), (3, $batch08$Goal$batch08$, $batch08$The mites can live only in a narrow range of climates.$batch08$)) v(position,label,body) WHERE q.qid=$batch08$PT159-S1-Q8$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch08$A$batch08$, $batch08$If the mites survive only in very specific climates, their presence 2,000 years ago means the cave had their climate then. Today that climate is found in the cooler area.$batch08$), ($batch08$B$batch08$, $batch08$If the cooler area is also wetter, moisture could be what the mites need. That is an alternative to temperature.$batch08$), ($batch08$C$batch08$, $batch08$Whether the mites lived there even earlier doesn't bear on the temperature 2,000 years ago.$batch08$), ($batch08$D$batch08$, $batch08$If altitude is what matters, the move could be about altitude, not temperature.$batch08$), ($batch08$E$batch08$, $batch08$How many species live there now doesn't tell us why these mites left.$batch08$)) v(letter,body) WHERE q.qid=$batch08$PT159-S1-Q8$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
